package android.app;public class AlertDialog {public static Builder last;public static class Builder {public android.content.DialogInterface.OnClickListener listener;public Builder(Activity a){last=this;}public Builder setTitle(String s){return this;}public Builder setItems(String[] s,android.content.DialogInterface.OnClickListener l){listener=l;return this;}public AlertDialog show(){return new AlertDialog();}public void select(int n){listener.onClick(null,n);}}}